using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class HospitalBillboardGeometryProbe{static HospitalBillboardGeometryProbe(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("HospitalBillboardGeometryProbe.request"))return;File.Delete("HospitalBillboardGeometryProbe.request");try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var f=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Single(g=>g.name=="billboard (8)");var d=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f.sharedMesh});var p=(Vector3[])d.GetType().GetField("p").GetValue(d);var ids=(int[])d.GetType().GetField("ids").GetValue(d);File.WriteAllLines("FinalEnvironmentRoadReview/HospitalBillboardFaces.txt",Enumerable.Range(0,ids.Length/3).Select(k=>{var a=f.transform.TransformPoint(p[ids[k*3]]);var b=f.transform.TransformPoint(p[ids[k*3+1]]);var c=f.transform.TransformPoint(p[ids[k*3+2]]);var n=Vector3.Cross(b-a,c-a);return new{a,b,c,n};}).Where(t=>t.n.magnitude>5).Select(t=>"area="+t.n.magnitude/2+" normal="+t.n.normalized+" a="+t.a+" b="+t.b+" c="+t.c));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/HospitalBillboardFaces.txt",e.ToString());}}}
